cypress_script:
describe('Login Functionality', () => {
  it('should log in with valid credentials', () => {
    cy.visit('https://automationexercise.com/login');
    cy.get('input[name="email"]').type('valid-email@example.com');
    cy.get('input[name="password"]').type('validPassword');
    cy.get('button[class="btn btn-default"][text="Login"]').click();
    cy.url().should('include', '/account');
  });

  it('should not log in with empty credentials', () => {
    cy.visit('https://automationexercise.com/login');
    cy.get('button[class="btn btn-default"][text="Login"]').click();
    cy.url().should('include', '/login');
    cy.get('div[id="form"]').should('be.visible');
  });
});

playwright_script:
import { test, expect } from '@playwright/test';

test.describe('Login Functionality', () => {
  test('should log in with valid credentials', async ({ page }) => {
    await page.goto('https://automationexercise.com/login');
    await page.fill('input[name="email"]', 'valid-email@example.com');
    await page.fill('input[name="password"]', 'validPassword');
    await page.click('button[class="btn btn-default"][text="Login"]');
    await expect(page).toHaveURL(/.*\/account/);
  });

  test('should not log in with empty credentials', async ({ page }) => {
    await page.goto('https://automationexercise.com/login');
    await page.click('button[class="btn btn-default"][text="Login"]');
    await expect(page).toHaveURL(/.*\/login/);
    await expect(page.locator('div[id="form"]').isVisible()).toBeTruthy();
  });
});
